create or replace function public.create_consultation(p_appointment_id uuid, p_symptoms text, p_clinical_notes text default null, p_assessment text default null, p_advice text default null, p_follow_up_date date default null) returns public.consultations language plpgsql security definer set search_path = public as $$ declare v_appointment public.appointments; v_consultation public.consultations; begin if auth.uid() is null or not public.is_doctor() then raise exception using errcode = '42501', message = 'Only authenticated doctors can create consultations'; end if; select * into v_appointment from public.appointments where id = p_appointment_id; if v_appointment.id is null then raise exception using errcode = '22023', message = 'Appointment not found'; end if; if not public.owns_doctor_profile(v_appointment.doctor_id) then raise exception using errcode = '42501', message = 'Only the assigned doctor can create a consultation'; end if; if not public.has_valid_record_consent(v_appointment.patient_id, v_appointment.doctor_id) then raise exception using errcode = '42501', message = 'Active patient consent is required'; end if; if v_appointment.status <> 'completed'::public.appointment_status then raise exception using errcode = '22023', message = 'Consultation requires a completed appointment'; end if; if length(trim(coalesce(p_symptoms, ''))) = 0 then raise exception using errcode = '22023', message = 'Symptoms are required'; end if; insert into public.consultations (appointment_id, patient_id, doctor_id, symptoms, clinical_notes, assessment, advice, follow_up_date) values (p_appointment_id, v_appointment.patient_id, v_appointment.doctor_id, p_symptoms, p_clinical_notes, p_assessment, p_advice, p_follow_up_date) returning * into v_consultation; return v_consultation; end; $$;
create or replace function public.create_prescription(p_consultation_id uuid, p_notes text default null, p_items jsonb default '[]'::jsonb) returns public.prescriptions language plpgsql security definer set search_path = public as $$ declare v_consultation public.consultations; v_prescription public.prescriptions; v_item jsonb; v_index integer := 0; v_medicine text; v_dosage text; v_frequency text; v_duration text; v_instructions text; begin if auth.uid() is null or not public.is_doctor() then raise exception using errcode = '42501', message = 'Only authenticated doctors can create prescriptions'; end if; select * into v_consultation from public.consultations where id = p_consultation_id; if v_consultation.id is null then raise exception using errcode = '22023', message = 'Consultation not found'; end if; if not public.owns_consultation_doctor(p_consultation_id) then raise exception using errcode = '42501', message = 'Only the consultation doctor can create a prescription'; end if; if not public.has_valid_record_consent(v_consultation.patient_id, v_consultation.doctor_id) then raise exception using errcode = '42501', message = 'Active patient consent is required'; end if; if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 50 then raise exception using errcode = '22023', message = 'A prescription must contain between 1 and 50 items'; end if; insert into public.prescriptions (consultation_id, patient_id, doctor_id, notes) values (v_consultation.id, v_consultation.patient_id, v_consultation.doctor_id, p_notes) returning * into v_prescription; for v_item in select value from jsonb_array_elements(p_items) loop v_medicine := nullif(trim(v_item->>'medicine_name'), ''); v_dosage := nullif(trim(v_item->>'dosage'), ''); v_frequency := nullif(trim(v_item->>'frequency'), ''); v_duration := nullif(trim(v_item->>'duration'), ''); v_instructions := nullif(trim(v_item->>'instructions'), ''); if v_medicine is null or v_dosage is null or v_frequency is null or v_duration is null then raise exception using errcode = '22023', message = 'Each prescription item requires medicine_name, dosage, frequency, and duration'; end if; insert into public.prescription_items (prescription_id, medicine_name, dosage, frequency, duration, instructions, sort_order) values (v_prescription.id, v_medicine, v_dosage, v_frequency, v_duration, v_instructions, v_index); v_index := v_index + 1; end loop; return v_prescription; exception when others then if v_prescription.id is not null then delete from public.prescriptions where id = v_prescription.id; end if; raise; end; $$;
